#include <Arduino.h>
#include <Arduino_GFX_Library.h>

// Определение пинов QSPI интерфейса дисплея AXS15231B для Waveshare 3.49"
#define LCD_QSPI_CS    9
#define LCD_QSPI_SCK   10
#define LCD_QSPI_D0    11
#define LCD_QSPI_D1    12
#define LCD_QSPI_D2    13
#define LCD_QSPI_D3    14
#define LCD_RESET      5

// Пин подсветки отличается в зависимости от версии (V1 или V2)
// Если экран не горит, проверьте версию платы или смените пин
#define LCD_BL         1    // Для V1 (для V2 может использоваться пин расширителя IO или другой GPIO)

// Нативное разрешение дисплея (в вертикальной ориентации)
#define WIDTH          172
#define HEIGHT         640

// Настройка QSPI интерфейса в Arduino_GFX
Arduino_DataBus *bus = new Arduino_ESP32QSPI(
    LCD_QSPI_CS, LCD_QSPI_SCK, LCD_QSPI_D0, LCD_QSPI_D1, LCD_QSPI_D2, LCD_QSPI_D3
);

// Инициализация драйвера AXS15231B
Arduino_GFX *gfx = new Arduino_AXS15231B(bus, LCD_RESET, 0 /* rotation */, false /* IPS */);

void setup() {
  Serial.begin(115200);

  // Включение подсветки дисплея
  pinMode(LCD_BL, OUTPUT);
  digitalWrite(LCD_BL, HIGH); 

  // Инициализация графического ядра
  if (!gfx->begin()) {
    Serial.println("Ошибка инициализации дисплея!");
    return;
  }

  gfx->fillScreen(BLACK);

  // Отрисовка цветных полос
  drawColorBars();
}

void loop() {
  // Цикл пустой, полосы статичны
}

void drawColorBars() {
  // Массив тестовых цветов в формате RGB565
  uint16_t colors[] = {
    WHITE,
    YELLOW,
    CYAN,
    GREEN,
    MAGENTA,
    RED,
    BLUE,
    BLACK
  };

  int numBars = sizeof(colors) / sizeof(colors[0]);

  // Так как экран очень вытянутый (172х640), логичнее сделать горизонтальные полосы, 
  // чтобы они корректно заполнили длину в 640 пикселей.
  uint16_t barHeight = HEIGHT / numBars;

  for (int i = 0; i < numBars; i++) {
    gfx->fillRect(0, i * barHeight, WIDTH, barHeight, colors[i]);
  }
}
